package client

import (
	"context"
	"net/http"
	"net/url"
)

// EndUserAPIKey mirrors the /v1/api_keys projection. Secret (credential
// "secret") or PrivateKey (credential "key_pair", generated by Atlas) is only
// present on create.
type EndUserAPIKey struct {
	ID         string   `json:"id"`
	KeyID      *string  `json:"key_id"`
	Name       *string  `json:"name"`
	Prefix     string   `json:"prefix"`
	Credential string   `json:"credential"`
	Audience   *string  `json:"audience"`
	PublicKey  *string  `json:"public_key"`
	OwnerType  string   `json:"subject_type"`
	OwnerID    string   `json:"subject_id"`
	Scopes     []string `json:"scopes"`
	CreatedAt  int64    `json:"created_at"`
	RevokedAt  *int64   `json:"revoked_at"`
	Secret     *string  `json:"secret"`
	PrivateKey *string  `json:"private_key"`
}

// EndUserAPIKeyCreate is the POST /v1/api_keys body.
type EndUserAPIKeyCreate struct {
	SubjectType string   `json:"subject_type"`
	SubjectID   string   `json:"subject_id"`
	Name        *string  `json:"name,omitempty"`
	Scopes      []string `json:"scopes,omitempty"`
	Credential  string   `json:"credential,omitempty"`
	Audience    *string  `json:"audience,omitempty"`
	PublicKey   *string  `json:"public_key,omitempty"`
}

// EndUserAPIKeyUpdate is the PATCH /v1/api_keys/:id body.
type EndUserAPIKeyUpdate struct {
	Name   *string   `json:"name,omitempty"`
	Scopes *[]string `json:"scopes,omitempty"`
}

func (c *Client) CreateEndUserAPIKey(ctx context.Context, body EndUserAPIKeyCreate) (*EndUserAPIKey, error) {
	var out EndUserAPIKey
	if err := c.do(ctx, http.MethodPost, "/v1/api_keys", body, &out); err != nil {
		return nil, err
	}
	return &out, nil
}

func (c *Client) GetEndUserAPIKey(ctx context.Context, id string) (*EndUserAPIKey, error) {
	var out EndUserAPIKey
	if err := c.do(ctx, http.MethodGet, "/v1/api_keys/"+url.PathEscape(id), nil, &out); err != nil {
		return nil, err
	}
	return &out, nil
}

func (c *Client) UpdateEndUserAPIKey(ctx context.Context, id string, body EndUserAPIKeyUpdate) (*EndUserAPIKey, error) {
	var out EndUserAPIKey
	if err := c.do(ctx, http.MethodPatch, "/v1/api_keys/"+url.PathEscape(id), body, &out); err != nil {
		return nil, err
	}
	return &out, nil
}

// RevokeEndUserAPIKey revokes the key (DELETE /v1/api_keys/:id).
func (c *Client) RevokeEndUserAPIKey(ctx context.Context, id string) error {
	return c.do(ctx, http.MethodDelete, "/v1/api_keys/"+url.PathEscape(id), nil, nil)
}
